/* The editorial half of an entry, and the half a generator cannot write.
   `options` expands the choice props the generated table can only name —
   `ButtonVariant` is a type, not an answer — and `notes` carries the contracts
   a three-column props table has no room for: what the component does NOT do,
   what the caller still owes it, and which prop wins when two disagree. */
type DocOption=[prop:string,values:string,note:ReactNode];
/* What an entry writes out by hand. `id` is a `GuidedId`, so an entry with no
   row in `guidance.ts` is a TYPE ERROR rather than a page that quietly reads as
   thinner than its neighbours — and `tsc --noEmit` runs inside `build:docs`, so
   it cannot be skipped. */
type DocEntry={id:GuidedId;name:string;group:"Foundations"|"Actions"|"Forms"|"Feedback"|"Overlays"|"Navigation"|"Mega menus"|"Surfaces & data"|"App patterns"|"Marketing & editorial";summary:string;code:string;preview:ReactNode;options?:DocOption[];notes?:ReactNode[]};
/* What the page actually renders and what the search indexes: the authored
   half plus the editorial half, merged at the one place both are known. */
