/* ── The overlay trap, shown rather than described ────────────────────
   The rule this page exists for is invisible in the stylesheet: a transformed
   ancestor becomes the containing block for its `position: fixed` descendants,
   so `inset: 0` silently stops meaning "the viewport". The scrim below is one
   element with one set of declarations; the only thing the toggle changes is
   whether its ANCESTOR carries a transform, and the measured box is printed so
   the reader does not have to take it on trust.

   The escaped state is `pointer-events: none` and sits under the docs chrome:
   a specimen may demonstrate the failure, it may not take the page ([[L48]]). */
function OverlayTrapDemo(){
 const[trapped,setTrapped]=useState(true);
 const[box,setBox]=useState("");
 const scrimRef=useRef<HTMLDivElement|null>(null);
 useEffect(()=>{
  const measure=()=>{const r=scrimRef.current?.getBoundingClientRect();if(r)setBox(`${Math.round(r.width)} × ${Math.round(r.height)}`)};
  const frame=requestAnimationFrame(measure);
  window.addEventListener("resize",measure);
  return()=>{cancelAnimationFrame(frame);window.removeEventListener("resize",measure)};
 },[trapped]);
 const viewport=typeof window==="undefined"?"":`${window.innerWidth} × ${window.innerHeight}`;
 return <div className="stack">
  <div className="trapdemo-stage">
   <div className="trapdemo-page">the page behind the sheet — this is what a scrim owes cover to</div>
   <div className="trapdemo-bar" style={trapped?{transform:"translateY(0px)"}:undefined}>
    <span>the bar — <code>transform: {trapped?"translateY(0px)":"none"}</code></span>
    <div className="trapdemo-scrim" ref={scrimRef} aria-hidden="true" data-escaped={trapped?undefined:""}><span>{`position: fixed; inset: 0 → ${box}`}</span></div>
   </div>
  </div>
  <div className="row">
   <Button variant={trapped?"primary":"secondary"} size="sm" onClick={()=>setTrapped(t=>!t)}>{trapped?"Remove the ancestor’s transform":"Put the transform back"}</Button>
   <span className="hint">Viewport is {viewport}. The scrim’s declarations never change.</span>
  </div>
 </div>;
}

