function CanvasDemo(){
 const camera=useRef<CanvasApi|null>(null);
 const [openId,setOpenId]=useState<string|null>(null);
 const [muted,setMuted]=useState(false);
 const open=CANVAS_NODES.find(n=>n.id===openId)??null;
 /* padRight here rather than relying on panelInset: the prop is a render
    behind a flight fired from the same handler that opens the panel. */
 const show=(node:typeof CANVAS_NODES[number])=>{setOpenId(node.id);camera.current?.flyTo(node,{max:1.4,padRight:400});};
 const back=()=>{setOpenId(null);camera.current?.fit();};
 return <Canvas
   ref={camera}
   label="How the systems connect"
   title="How the systems connect"
   description="Drag to pan, hold ⌘ and scroll to zoom, open a system to read it."
   world={CANVAS_WORLD}
   panelInset={open?400:0}
   allowFullscreen
   sound={{muted,onToggle:()=>setMuted(m=>!m)}}
   onReset={back}
   style={{height:420}}
   hint="drag to pan · ⌘ or ctrl + scroll to zoom · click a system"
   onEscape={back}
   breadcrumb={open?<Breadcrumbs items={[{label:"The estate",href:"#canvas"},{label:open.label}]} renderLink={({className,children})=><button type="button" className={className} onClick={back} style={{appearance:"none",border:0,background:"none",cursor:"pointer",font:"inherit"}}>{children}</button>}/>:null}
   panel={<CanvasPanel open={Boolean(open)} onClose={back} contentKey={open?.id} accent={open?.accent} title={open?.label??""}
     actions={<Button size="sm" onClick={back}>Back to the estate</Button>}>
     <p className="td-body" style={{margin:0}}>{open?.note}</p>
     <p className="td-fine" style={{margin:0,color:"var(--td-ink-3)"}}>The map stays live behind this — pan it while you read.</p>
   </CanvasPanel>}
 >
  {CANVAS_NODES.map(node=><CanvasNode key={node.id} x={node.x} y={node.y} w={node.w} h={node.h}
    title={node.label} sub={node.sub} accent={node.accent}
    selected={node.id===openId} dimmed={Boolean(openId)&&node.id!==openId}
    onClick={()=>show(node)}/>)}
 </Canvas>;
}
