/* ── The WhatsApp form builder ────────────────────────────────────────
   A playground rather than a preview, because this component's whole surface
   is a set of decisions — which named form, which questions, which of your own,
   and the number it all goes to — and a static specimen can only ever show one
   of them. Change anything and both the live form and the code under it move,
   so what you copy is exactly what you just pressed. */
const WA_FIELDS:WhatsAppFormField[]=["name","email","phone","subject","company","industry","service","message"];
const WA_MODES:WhatsAppFieldMode[]=["required","optional","off"];
type WaCustomDraft={id:string;label:string;kind:NonNullable<WhatsAppCustomField["kind"]>;mode:WhatsAppFieldMode};

function waCode(variant:WhatsAppFormVariant,number:string,overrides:Partial<Record<WhatsAppFormField,WhatsAppFieldMode>>,custom:WaCustomDraft[]){
 const lines=[`import { WhatsAppForm } from "@mithtech-bengaluru/tonaldepth-react";`,``,`<WhatsAppForm`];
 lines.push(`  phone="${number||"+91 98765 43210"}"`);
 if(variant!=="enquiry")lines.push(`  variant="${variant}"`);
 const keys=Object.keys(overrides) as WhatsAppFormField[];
 if(keys.length)lines.push(`  fields={{ ${keys.map(k=>`${k}: "${overrides[k]}"`).join(", ")} }}`);
 if(custom.length){
  lines.push(`  extraFields={[`);
  for(const f of custom){
   const bits=[`id: "${f.id}"`,`label: "${f.label}"`];
   if(f.kind!=="text")bits.push(`kind: "${f.kind}"`);
   if(f.mode!=="optional")bits.push(`mode: "${f.mode}"`);
   lines.push(`    { ${bits.join(", ")} },`);
  }
  lines.push(`  ]}`);
 }
 lines.push(`/>`);
 return lines.join("\n");
}

function WhatsAppBuilder(){
 const[variant,setVariant]=useState<WhatsAppFormVariant>("enquiry");
 const[number,setNumber]=useState("+91 98765 43210");
 const[overrides,setOverrides]=useState<Partial<Record<WhatsAppFormField,WhatsAppFieldMode>>>({});
 const[custom,setCustom]=useState<WaCustomDraft[]>([]);
 const[draft,setDraft]=useState<WaCustomDraft>({id:"",label:"",kind:"text",mode:"optional"});
 const spec=WHATSAPP_FORM_VARIANTS[variant];
 const effective=(field:WhatsAppFormField)=>overrides[field]??spec.fields[field];
 const setField=(field:WhatsAppFormField,mode:WhatsAppFieldMode)=>setOverrides(current=>{
  const next={...current};
  /* An override that matches the variant is not an override — dropping it
     keeps the generated `fields` prop to what actually differs, which is what
     a reader has to be able to see at a glance. */
  if(mode===spec.fields[field])delete next[field]; else next[field]=mode;
  return next;
 });
 const addCustom=()=>{
  const id=draft.id.trim()||draft.label.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
  if(!id||!draft.label.trim())return;
  setCustom(list=>[...list.filter(f=>f.id!==id),{...draft,id,label:draft.label.trim()}]);
  setDraft({id:"",label:"",kind:"text",mode:"optional"});
 };
 return <div className="playground">
  <div className="playground-controls">
   <label>Form<select value={variant} onChange={e=>{setVariant(e.target.value as WhatsAppFormVariant);setOverrides({});}}>
    {(Object.keys(WHATSAPP_FORM_VARIANTS) as WhatsAppFormVariant[]).map(key=><option key={key} value={key}>{WHATSAPP_FORM_VARIANTS[key].name}</option>)}
   </select></label>
   <label style={{minWidth:200}}>Send to<Input value={number} onChange={e=>setNumber(e.target.value)} placeholder="+91 98765 43210"/></label>
  </div>
  <p className="hint" style={{margin:0}}>{spec.description}</p>

  <div className="wa-build-grid">
   {WA_FIELDS.map(field=><label key={field} className="wa-build-field">
    <span>{field}</span>
    <select value={effective(field)} onChange={e=>setField(field,e.target.value as WhatsAppFieldMode)}>
     {WA_MODES.map(m=><option key={m} value={m}>{m}</option>)}
    </select>
   </label>)}
  </div>

  <div className="wa-build-custom">
   <span className="td-widget-eyebrow">Questions of your own</span>
   {custom.length?<ul className="wa-build-list">{custom.map(f=><li key={f.id}>
    <code>{f.id}</code> <strong>{f.label}</strong> <span className="hint">{f.kind} · {f.mode}</span>
    <Button variant="ghost" size="sm" onClick={()=>setCustom(list=>list.filter(x=>x.id!==f.id))}>Remove</Button>
   </li>)}</ul>:<p className="hint" style={{margin:0}}>None yet. The eight above are the built-ins; anything else you need is added here.</p>}
   <div className="playground-controls">
    <label>Label<Input value={draft.label} onChange={e=>setDraft({...draft,label:e.target.value})} placeholder="Fleet size"/></label>
    <label>Kind<select value={draft.kind} onChange={e=>setDraft({...draft,kind:e.target.value as WaCustomDraft["kind"]})}>
     {["text","email","tel","number","textarea","choice"].map(k=><option key={k} value={k}>{k}</option>)}
    </select></label>
    <label>Mode<select value={draft.mode} onChange={e=>setDraft({...draft,mode:e.target.value as WhatsAppFieldMode})}>
     {["optional","required"].map(m=><option key={m} value={m}>{m}</option>)}
    </select></label>
    <Button variant="outline" size="sm" onClick={addCustom}>Add the field</Button>
   </div>
  </div>

  <div className="row" style={{alignItems:"center",gap:16}}>
   <WhatsAppForm
    key={`${variant}-${custom.map(f=>f.id).join()}-${Object.keys(overrides).join()}`}
    phone={number}
    variant={variant}
    fields={overrides}
    extraFields={custom.map(f=>({id:f.id,label:f.label,kind:f.kind,mode:f.mode}))}
    services={["ERP implementation","Commerce","Automation","Managed operations"]}
    industries={["Manufacturing","Retail","Healthcare","Logistics"]}
   />
   <span className="hint">Opens the real form. Nothing is submitted — pressing the green button hands the composed message to <code>wa.me</code>.</span>
  </div>

  <CodeBlock language="TSX" title="What you just built" code={waCode(variant,number,overrides,custom)} copy/>
 </div>;
}

