/* The reverse geocode the component deliberately does not ship.

   OpenStreetMap's Nominatim is the obvious free choice and it is the reason
   this is a prop rather than a built-in: its usage policy requires a per-
   application identity and caps request rate, which is a term a component
   cannot accept on a consumer's behalf. Paste this, or point it at whatever
   you already pay for. */
async function nominatimReverse({latitude,longitude}:{latitude:number;longitude:number}){
 const url=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}&addressdetails=1`;
 const r=await fetch(url,{headers:{Accept:"application/json"}});
 if(!r.ok) throw new Error(`Nominatim ${r.status}`);
 const a=(await r.json()).address??{};
 return {
  line1:[a.house_number,a.road].filter(Boolean).join(" "),
  line2:a.suburb??a.neighbourhood??"",
  city:a.city??a.town??a.village??a.county??"",
  state:a.state??"",
  postcode:a.postcode??"",
  country:a.country??"",
 };
}
